// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *ProjectBudgetEntry) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectBudgetEntryTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "entry_no":
			column = "entry_no"
		case "quantity":
			column = "quantity"
		case "total_cost":
			column = "total_cost"
		case "total_price":
			column = "total_price"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Project_Budget_Entry", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Project_Budget_Entry.%s: %w", column, err)
		}
		switch column {
		case "entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Project_Budget_Entry.%s: %w", column, err)
			}
			t.Entry_no = int(f)
		case "quantity":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Project_Budget_Entry.%s: %w", column, err)
			}
			t.Quantity = d
		case "total_cost":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Project_Budget_Entry.%s: %w", column, err)
			}
			t.Total_cost = d
		case "total_price":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Project_Budget_Entry.%s: %w", column, err)
			}
			t.Total_price = d
		}
	}
	return nil
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
// table lock (tables.LockTable) and the following reads (Get, FindFirst, FindLast, FindSet)
// lock the rows they read (SELECT … FOR UPDATE); SQLite locks the whole database on write
// anyway. Use it inside a transaction.
func (t *ProjectBudgetEntry) LockTable() {
	if !t.lockForUpdate {
		tables.LockTable(t.db, t.dbType, t.company, ProjectBudgetEntryTableName)
	}
	t.lockForUpdate = true
}

func (t *ProjectBudgetEntry) forUpdate() string {
	if t.lockForUpdate && t.dbType == database.DBTypePostgres {
		return " FOR UPDATE"
	}
	return ""
}

